#!/usr/bin/env node
/**
 * sync-format-guide.mjs
 *
 * Build-time transform: reads docs/sstables-definitive-guide/chapters/ and
 * emits Starlight-ready pages into website/src/content/docs/sstable-format/.
 *
 * Also copies SVG diagrams from docs/sstables-definitive-guide/diagrams/ to
 * website/public/format-guide/diagrams/ so the built site can serve them.
 *
 * The generated files are gitignored. The committed
 * website/src/content/docs/sstable-format/index.md is regenerated by this
 * script from the canonical chapter list — it is deterministic, so committing
 * it would be redundant. See the note in website/README.md.
 *
 * Usage: node website/scripts/sync-format-guide.mjs
 *        (called automatically by prebuild/predev in package.json)
 *
 * Design decisions:
 *  1. No new npm dependencies — plain Node.js fs/path/url.
 *  2. Title extracted from the first H2 (chapters have no H1 frontmatter).
 *     Appendix A uses an H1, which is also handled.
 *  3. Diagram references ![alt](diagrams/name) → ![alt](/cqlite/format-guide/diagrams/name.svg)
 *  4. Intra-guide links ./NN-slug.md → /cqlite/sstable-format/chNN-slug/
 *     and ./appendix-X-slug.md → /cqlite/sstable-format/appendix-X-slug/
 *  5. Code-transclusion fence headers (```N:M:/abs/path) are cleaned to plain ```
 *  6. The index.md is always regenerated with the canonical chapter map.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const CHAPTERS_DIR = path.join(REPO_ROOT, 'docs', 'sstables-definitive-guide', 'chapters');
const DIAGRAMS_SRC = path.join(REPO_ROOT, 'docs', 'sstables-definitive-guide', 'diagrams');
const OUTPUT_DIR = path.join(__dirname, '..', 'src', 'content', 'docs', 'sstable-format');
const DIAGRAMS_DST = path.join(__dirname, '..', 'public', 'format-guide', 'diagrams');

// Base path for the deployed site (matches astro.config.mjs base: '/cqlite')
const SITE_BASE = '/cqlite';

// Canonical chapter ordering: [slug-suffix, sidebar-order, human-title]
// These are the chapters published to the site (matches README.md outline).
const CHAPTERS = [
  // Chapters 01–22
  { file: '01-what-are-sstables.md',           order: 1,  prefix: 'ch01' },
  { file: '02-anatomy-of-an-sstable.md',        order: 2,  prefix: 'ch02' },
  { file: '03-disk-and-io-model.md',            order: 3,  prefix: 'ch03' },
  { file: '04-from-cql-to-disk.md',             order: 4,  prefix: 'ch04' },
  { file: '05-data-db-format.md',               order: 5,  prefix: 'ch05' },
  { file: '06-index-and-summary.md',            order: 6,  prefix: 'ch06' },
  { file: '07-bloom-filter.md',                 order: 7,  prefix: 'ch07' },
  { file: '08-statistics-db.md',                order: 8,  prefix: 'ch08' },
  { file: '09-compressioninfo-and-chunking.md', order: 9,  prefix: 'ch09' },
  { file: '10-point-reads-and-slices.md',       order: 10, prefix: 'ch10' },
  { file: '11-merging-tombstones-and-shadowing.md', order: 11, prefix: 'ch11' },
  { file: '12-caching-and-os-interaction.md',   order: 12, prefix: 'ch12' },
  { file: '13-secondary-indexes.md',            order: 13, prefix: 'ch13' },
  { file: '14-storage-attached-indexes-sai.md', order: 14, prefix: 'ch14' },
  { file: '15-compaction-strategies.md',        order: 15, prefix: 'ch15' },
  { file: '16-sstable-lifecycle-and-maintenance.md', order: 16, prefix: 'ch16' },
  { file: '17-bti-formats.md',                  order: 17, prefix: 'ch17' },
  { file: '18-repair-streaming-bootstrap.md',   order: 18, prefix: 'ch18' },
  { file: '19-incremental-backups-and-snapshots.md', order: 19, prefix: 'ch19' },
  { file: '20-checksums-and-integrity.md',      order: 20, prefix: 'ch20' },
  { file: '21-how-to-find-a-row-by-key.md',     order: 21, prefix: 'ch21' },
  { file: '22-versioning-matrix.md',            order: 22, prefix: 'ch22' },
  // Appendices
  { file: 'appendix-a-type-mapping.md',         order: 101, prefix: 'appendix-a' },
  { file: 'appendix-b-encodings-cheat-sheet.md',order: 102, prefix: 'appendix-b' },
  { file: 'appendix-c-walkthroughs.md',         order: 103, prefix: 'appendix-c' },
  { file: 'appendix-d-tools-and-workflows.md',  order: 104, prefix: 'appendix-d' },
  { file: 'appendix-e-glossary.md',             order: 105, prefix: 'appendix-e' },
  { file: 'appendix-f-known-limitations.md',    order: 106, prefix: 'appendix-f' },
  { file: 'appendix-g-compression-chunk-formats.md', order: 107, prefix: 'appendix-g' },
];

// Map from source filename → output slug for link rewriting
const FILE_TO_SLUG = new Map();
for (const ch of CHAPTERS) {
  FILE_TO_SLUG.set(ch.file, ch.prefix);
}

/**
 * Extract a human-readable title from chapter content.
 * Chapters use ## H2 as the first heading (no H1 except a few appendices).
 * Returns the text of the first H1 or H2 found, stripped of markdown inline.
 */
function extractTitle(content) {
  // Try H1 first (some appendices), then H2
  const h1 = content.match(/^#\s+(.+)$/m);
  if (h1) return h1[1].trim().replace(/[*_`]/g, '');
  const h2 = content.match(/^##\s+(.+)$/m);
  if (h2) return h2[1].trim().replace(/[*_`]/g, '');
  return 'Untitled';
}

/**
 * Rewrite content for Starlight rendering:
 *  1. Strip the leading H1 (if present) — frontmatter title replaces it.
 *  2. Rewrite diagram references ![alt](diagrams/name) or ![alt](diagrams/name.svg).
 *  3. Rewrite intra-guide .md links: ./NN-slug.md → /cqlite/sstable-format/chNN-slug/
 *  4. Clean code-transclusion fence markers ```N:M:/abs/path → ``` (no lang).
 *  5. Leave external links and GitHub links untouched.
 */
function transformContent(content, chapterFile) {
  let out = content;

  // 1. Strip leading H1 if present (Starlight injects title from frontmatter)
  out = out.replace(/^#\s+.+\n/, '');

  // 2. Rewrite diagram references (with or without .svg / .pdf extensions)
  //    Pattern: ![alt text](diagrams/name) or ![alt text](diagrams/name.svg)
  //    Rewrite to: ![alt text](/cqlite/format-guide/diagrams/name.svg)
  out = out.replace(
    /!\[([^\]]*)\]\(diagrams\/([^).]+?)(?:\.svg|\.pdf|\.mmd)?\)/g,
    (_, alt, name) => `![${alt}](${SITE_BASE}/format-guide/diagrams/${name}.svg)`
  );
  // Also handle the text reference style in ch01: `../diagrams/sstable-components.svg`
  out = out.replace(
    /`\.\.\/diagrams\/([^`]+?)(?:\.svg|\.mmd|\.pdf)?`/g,
    (_, name) => `\`${SITE_BASE}/format-guide/diagrams/${name}\``
  );

  // 3. Rewrite intra-guide relative .md links
  //    Handles both ./NN-slug.md and bare NN-slug.md (no ./ prefix) forms.
  //    Pattern: [text](./NN-slug.md[#anchor]) or [text](NN-slug.md[#anchor])
  //    Also: [text](./appendix-X-slug.md) or [text](appendix-X-slug.md)
  const rewriteIntraLink = (_, linkText, slug, anchor) => {
    const outputSlug = FILE_TO_SLUG.get(slug + '.md');
    if (outputSlug) {
      const anchorPart = anchor || '';
      return `[${linkText}](${SITE_BASE}/sstable-format/${outputSlug}/${anchorPart})`;
    }
    // Fallback: link to GitHub source
    return `[${linkText}](https://github.com/pmcfadin/cqlite/blob/main/docs/sstables-definitive-guide/chapters/${slug}.md${anchor || ''}) <!-- TODO(W8): site link -->`;
  };
  // With ./ prefix
  out = out.replace(
    /\[([^\]]*)\]\(\.\/((?:[0-9]{2}-[^)#\s]+|appendix-[^)#\s]+))\.md(#[^)]*)?\)/g,
    rewriteIntraLink
  );
  // Without ./ prefix (bare relative links like appendix-b-encodings-cheat-sheet.md)
  // Use negative lookbehind to avoid matching absolute URLs or already-rewritten links
  out = out.replace(
    /\[([^\]]*)\]\(((?:[0-9]{2}-[^)#\s]+|appendix-[^)#\s]+))\.md(#[^)]*)?\)/g,
    rewriteIntraLink
  );

  // 4. Clean code-transclusion fence headers: ```N:M:/abs/path → ```
  //    These are editor-specific inline-file-content markers used during authoring.
  //    The content that follows is already rendered inline (the lines after the marker).
  out = out.replace(/^```[0-9]+:[0-9]+:\/[^\n]*$/gm, '```');

  // 5. Rewrite absolute repo-path references in text (like file path references)
  //    `/docs/sstables-definitive-guide/chapters/XX.md` → site slug
  out = out.replace(
    /`\/docs\/sstables-definitive-guide\/chapters\/((?:[0-9]{2}-[^`]+|appendix-[^`]+))\.md`/g,
    (_, slug) => {
      const outputSlug = FILE_TO_SLUG.get(slug + '.md');
      if (outputSlug) {
        return `[\`${slug}.md\`](${SITE_BASE}/sstable-format/${outputSlug}/)`;
      }
      return `\`${slug}.md\``;
    }
  );

  return out;
}

/**
 * Build a short description from content (first non-heading paragraph).
 */
function extractDescription(content) {
  // Strip front matter, then find first paragraph of real text
  const lines = content.split('\n');
  let inHeading = false;
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('#')) { inHeading = true; continue; }
    if (inHeading && trimmed.length === 0) { inHeading = false; continue; }
    if (!inHeading && trimmed.length > 20 && !trimmed.startsWith('-') && !trimmed.startsWith('|') && !trimmed.startsWith('```') && !trimmed.startsWith('>')) {
      // Truncate to ~150 chars for description
      return trimmed.replace(/[*_`[\]]/g, '').substring(0, 150).replace(/\s+\S*$/, '') + '...';
    }
  }
  return '';
}

// ── Main ─────────────────────────────────────────────────────────────────────

console.log('[sync-format-guide] Starting...');

// Ensure output directories exist
fs.mkdirSync(OUTPUT_DIR, { recursive: true });
fs.mkdirSync(DIAGRAMS_DST, { recursive: true });

// Copy all SVG diagrams
const svgFiles = fs.readdirSync(DIAGRAMS_SRC).filter(f => f.endsWith('.svg'));
for (const svg of svgFiles) {
  fs.copyFileSync(
    path.join(DIAGRAMS_SRC, svg),
    path.join(DIAGRAMS_DST, svg)
  );
}
console.log(`[sync-format-guide] Copied ${svgFiles.length} SVG diagrams to public/format-guide/diagrams/`);

// Track chapters for index.md generation
const indexEntries = [];

// Transform and emit each chapter
let count = 0;
for (const ch of CHAPTERS) {
  const srcPath = path.join(CHAPTERS_DIR, ch.file);
  if (!fs.existsSync(srcPath)) {
    console.warn(`[sync-format-guide] WARN: source not found: ${srcPath}`);
    continue;
  }

  const rawContent = fs.readFileSync(srcPath, 'utf-8');
  const title = extractTitle(rawContent);
  const description = extractDescription(rawContent);
  const body = transformContent(rawContent, ch.file);

  // Build frontmatter
  const sidebarLabel = title.length > 60 ? title.substring(0, 57) + '...' : title;
  const frontmatter = [
    '---',
    `title: "${title.replace(/"/g, '\\"')}"`,
    description ? `description: "${description.replace(/"/g, '\\"')}"` : '',
    'sidebar:',
    `  label: "${sidebarLabel.replace(/"/g, '\\"')}"`,
    `  order: ${ch.order}`,
    '---',
    '',
  ].filter(l => l !== null).join('\n');

  const outputPath = path.join(OUTPUT_DIR, ch.prefix + '.md');
  fs.writeFileSync(outputPath, frontmatter + body, 'utf-8');
  count++;

  // Record for index
  indexEntries.push({ prefix: ch.prefix, title, order: ch.order, isAppendix: ch.prefix.startsWith('appendix') });
}

console.log(`[sync-format-guide] Emitted ${count} chapter pages`);

// Generate index.md — deterministic chapter map landing page
const chapterEntries = indexEntries.filter(e => !e.isAppendix);
const appendixEntries = indexEntries.filter(e => e.isAppendix);

function makeEntry(e) {
  return `- [${e.title}](/cqlite/sstable-format/${e.prefix}/)`;
}

const indexContent = `---
title: "SSTable Format Guide"
description: "22-chapter deep dive into the Cassandra 5.0 SSTable binary format, audited against Cassandra 5.0.8."
sidebar:
  label: "Overview"
  order: 0
---

# SSTable Format Guide

A 22-chapter reference for the Apache Cassandra 5.0 SSTable binary format, audited against Cassandra 5.0.8 as part of CQLite epic #598.

> Source of truth: [\`docs/sstables-definitive-guide/\`](https://github.com/pmcfadin/cqlite/tree/main/docs/sstables-definitive-guide/) — pages below are generated at build time by \`website/scripts/sync-format-guide.mjs\`.

## Chapters

${chapterEntries.map(makeEntry).join('\n')}

## Appendices

${appendixEntries.map(makeEntry).join('\n')}
`;

fs.writeFileSync(path.join(OUTPUT_DIR, 'index.md'), indexContent, 'utf-8');
console.log('[sync-format-guide] Regenerated index.md');

console.log('[sync-format-guide] Done.');
